#!/bin/zsh
# 🧫️ The search run of one plant on a copy: `rebind.ts` when column 4 of `plants.tsv` starts with `rebind` (its further words are flags of `rebind.ts`), the asset's own `fix-<id>.ts` if there is one, `bodyview.ts` when `bodyview/<id>.json` exists, `prism.ts` when `prism/<id>.json` exists, `crown500.ts` when `crown500/<id>.json` exists, then `carry.ts`, from the catalog file into `$GEN/try/<id>.json`, the anchor search on that copy (ops saved to `ops/<id>.json`), then the gate over every subject and the print suitability of every authored scale (`suit.ts`). Nothing in the catalog is written. Every step runs through the machine-wide memory queue (`q.sh`, 1000 MB). The flags of a plant for `carry.ts` and for the anchor search are columns 2 and 3 of `plants.tsv`. trial.sh <id> [more carry flags…]   (NOCARRY=1, or `-` in column 2, leaves `carry.ts` out)
BATCH=MV-3 source "${0:A:h}/../MR/env.sh"
q() { if [[ -n "$MV3_GRANT" ]]; then local dir="$2" t="$3" r="$GEN/log/rss-$$.txt" code; shift 3; (cd "$dir" && /usr/bin/time -l -o "$r" timeout "$t" "$@"); code=$?; echo "$(( $(awk '/maximum resident set size/{print $1}' "$r") / 1048576 )) MB ${${@[2,5]}:t}" >> "$GEN/log/rss.txt"; rm -f "$r"; return $code; else "$W/q.sh" "$@"; fi }
a="$1"; shift; cf=(${=$(awk -F'\t' -v a="$a" '$1==a{print $2}' "$W/plants.tsv")}); af=(${=$(awk -F'\t' -v a="$a" '$1==a{print $3}' "$W/plants.tsv")}); mkdir -p "$GEN/try" "$GEN/log" "$W/ops"
rm -f "$GEN/try/$a.json"; src="$a"; rb=(${=$(awk -F'\t' -v a="$a" '$1==a{print $4}' "$W/plants.tsv")}); if [[ "$rb[1]" == rebind ]]; then q 1000 "$T" 900 "$B" "$W/rebind.ts" "$a" --out "$GEN/try/$a.json" $rb[2,-1] | tail -1; src="$GEN/try/$a.json"; fi
if [[ -f "$W/fix-$a.ts" ]]; then q 1000 "$T" 600 "$B" "$W/fix-$a.ts" --out "$GEN/try/$a.json" | tail -1; src="$GEN/try/$a.json"; fi
if [[ -f "$W/bodyview/$a.json" ]]; then q 1000 "$T" 1800 "$B" "$W/bodyview.ts" "$src" --work "$GEN/work" --out "$GEN/try/$a.json" > "$GEN/log/$a-bodyview.log" 2>&1; echo "bodyview exit $? $(grep -v DEBUG "$GEN/log/$a-bodyview.log" | tail -1 | cut -c1-160)"; src="$GEN/try/$a.json"; fi
if [[ -f "$W/prism/$a.json" ]]; then q 1000 "$T" 1800 "$B" "$W/prism.ts" "$src" --out "$GEN/try/$a.json" > "$GEN/log/$a-prism.log" 2>&1; echo "prism exit $? $(grep -v DEBUG "$GEN/log/$a-prism.log" | tail -1 | cut -c1-200)"; src="$GEN/try/$a.json"; fi
if [[ -f "$W/crown500/$a.json" ]]; then q 1000 "$T" 900 "$B" "$W/crown500.ts" "$src" --out "$GEN/try/$a.json" > "$GEN/log/$a-crown500.log" 2>&1; echo "crown500 exit $? $(grep -v DEBUG "$GEN/log/$a-crown500.log" | tail -1 | cut -c1-160)"; src="$GEN/try/$a.json"; fi
[[ -n "$NOCARRY" || "$cf[1]" == "-" ]] || q 1000 "$T" 3000 "$B" "$W/carry.ts" "$src" --out "$GEN/try/$a.json" $cf "$@" > "$GEN/log/$a-carry.log" 2>&1; echo "carry exit $? $(grep -c 'STILL BEYOND' "$GEN/log/$a-carry.log") beyond; $(grep 'plates with' "$GEN/log/$a-carry.log")"
[[ -f "$GEN/try/$a.json" ]] || cp "$(ls "$S"/🗂️catalog/*/"$a"/🔣️.json)" "$GEN/try/$a.json"
q 1000 "$T" 3000 "$B" "$W/anchors.ts" "$GEN/try/$a.json" --save "$W/ops/$a.json" --out "$GEN/try/$a.json" $af > "$GEN/log/$a-anchors.log" 2>&1; echo "anchors exit $? $(tail -2 "$GEN/log/$a-anchors.log" | head -1 | cut -c1-200)"
q 1000 "$T" 1800 "$B" "$M/gate.ts" "$GEN/try/$a.json" > "$GEN/log/$a-gate.log" 2>&1; echo "gate exit $? $(tail -1 "$GEN/log/$a-gate.log")"
q 1000 "$T" 900 "$B" "$W/suit.ts" "$GEN/try/$a.json" > "$GEN/log/$a-suit.log" 2>&1; echo "suit exit $? $(tail -1 "$GEN/log/$a-suit.log")"
